Action: run_sql({'query': "SELECT e.gmap_id, e.name, e.address, e.avg_rating, e.num_of_reviews, ST_Y(e.geom) as lat, ST_X(e.geom) as lon,\n       STRING_AGG(DISTINCT c.category, ', ') as categories\nFROM establishments e\nLEFT JOIN establishment_categories ec ON e.gmap_id = ec.gmap_id\nLEFT JOIN category c ON ec.category_id = c.category_id\nWHERE ST_DWithin(e.geom, ST_Point(-111.925, 40.785)::GEOMETRY, 0.03) -- roughly 2 miles\nGROUP BY e.gmap_id, e.name, e.address, e.avg_rating, e.num_of_reviews, e.geom\nHAVING LOWER(STRING_AGG(DISTINCT c.category, ', ')) LIKE '%breakfast%'\n    OR LOWER(STRING_AGG(DISTINCT c.category, ', ')) LIKE '%diner%'\n    OR LOWER(STRING_AGG(DISTINCT c.category, ', ')) LIKE '%mexican%'\n    OR LOWER(STRING_AGG(DISTINCT c.category, ', ')) LIKE '%cafe%'\n    OR LOWER(STRING_AGG(DISTINCT c.category, ', ')) LIKE '%burrito%'\n    OR LOWER(STRING_AGG(DISTINCT c.category, ', ')) LIKE '%american%'\n    OR LOWER(e.name) LIKE '%breakfast%'\n    OR LOWER(e.name) LIKE '%cafe%'\n    OR LOWER(e.name) LIKE '%diner%'\n    OR LOWER(e.name) LIKE '%grill%'\n    OR LOWER(e.name) LIKE '%taco%'\n    OR LOWER(e.name) LIKE '%burrito%'\nORDER BY e.num_of_reviews DESC\nLIMIT 30;"})

