Action: run_sql({'query': "SELECT e.name, e.address, e.avg_rating, e.num_of_reviews, e.price,\n       e.slchd_establishment_key,\n       STRING_AGG(DISTINCT c.category, ', ') as categories\nFROM establishments e\nLEFT JOIN establishment_categories ec ON e.gmap_id = ec.gmap_id\nLEFT JOIN category c ON ec.category_id = c.category_id\nWHERE (e.address ILIKE '%84116%' OR ST_DWithin(e.geom, ST_Point(-111.925, 40.785)::GEOMETRY, 0.025))\n  AND (\n       LOWER(STRING_AGG(DISTINCT c.category, ', ')) LIKE '%mexican%'\n    OR LOWER(STRING_AGG(DISTINCT c.category, ', ')) LIKE '%diner%'\n    OR LOWER(STRING_AGG(DISTINCT c.category, ', ')) LIKE '%breakfast%'\n    OR LOWER(STRING_AGG(DISTINCT c.category, ', ')) LIKE '%american%'\n    OR LOWER(STRING_AGG(DISTINCT c.category, ', ')) LIKE '%burrito%'\n    OR LOWER(e.name) LIKE '%chubby%'\n    OR LOWER(e.name) LIKE '%cabrito%'\n    OR LOWER(e.name) LIKE '%santo%'\n    OR LOWER(e.name) LIKE '%denny%'\n    OR LOWER(e.name) LIKE '%nico%'\n    OR LOWER(e.name) LIKE '%rancherito%'\n    OR LOWER(e.name) LIKE '%hacienda%'\n    OR LOWER(e.name) LIKE '%asadero%'\n  )\nGROUP BY e.name, e.address, e.avg_rating, e.num_of_reviews, e.price, e.slchd_establishment_key, e.geom\nHAVING e.num_of_reviews >= 50\nORDER BY e.avg_rating DESC, e.num_of_reviews DESC;"})

