Action: run_sql({'query': "WITH cat_agg AS (\n    SELECT e.gmap_id, e.name, e.address, e.avg_rating, e.num_of_reviews, e.price,\n           e.slchd_establishment_key, ST_Y(e.geom) as lat, ST_X(e.geom) as lon,\n           STRING_AGG(DISTINCT c.category, ', ') as categories\n    FROM establishments e\n    LEFT JOIN establishment_categories ec ON e.gmap_id = ec.gmap_id\n    LEFT JOIN category c ON ec.category_id = c.category_id\n    WHERE e.address ILIKE '%84116%' OR ST_DWithin(e.geom, ST_Point(-111.925, 40.785)::GEOMETRY, 0.025)\n    GROUP BY e.gmap_id, e.name, e.address, e.avg_rating, e.num_of_reviews, e.price, e.slchd_establishment_key, e.geom\n)\nSELECT name, address, avg_rating, num_of_reviews, price, categories, slchd_establishment_key, lat, lon\nFROM cat_agg\nWHERE num_of_reviews >= 50\n  AND (\n       LOWER(categories) LIKE '%mexican%'\n    OR LOWER(categories) LIKE '%diner%'\n    OR LOWER(categories) LIKE '%breakfast%'\n    OR LOWER(categories) LIKE '%american%'\n    OR LOWER(categories) LIKE '%burrito%'\n    OR LOWER(categories) LIKE '%cafe%'\n    OR LOWER(name) LIKE '%chubby%'\n    OR LOWER(name) LIKE '%cabrito%'\n    OR LOWER(name) LIKE '%santo%'\n  )\nORDER BY avg_rating DESC, num_of_reviews DESC;"})

